"use strict";
    // =====================================================================
    // VantNet Haiti — Boutique client — fichier unique (HTML + CSS + JS)
    // Sommaire rapide de ce script :
    //   1. Config Supabase + état global (state)
    //   2. Lecture/écriture Supabase (readStore, writeStore, writeRow, upload)
    //   3. Chargement initial (seedData) + écoute temps réel (setupRealtimeListeners)
    //   4. Session client (localStorage) + authentification + mot de passe oublié
    //   5. Rendu boutique (grille produits, filtres, panier)
    //   6. Fiche produit (galerie + contenance ml) — renderProductDetailModal
    //   7. Commande / checkout
    //   8. Écouteurs d'événements globaux (clics, formulaires)
    // =====================================================================

    // SUPABASE CONFIGURATION (partagée via js/config.js → window.MH)
    const { SUPABASE_URL, SUPABASE_ANON_KEY } = window.MH;
    // Paiement automatisé via Bazik (MonCash/NatCash) — Edge Functions Supabase,
    // les clés secrètes Bazik ne circulent jamais côté client.
    const PAYMENT_CREATE_URL = window.MH.PAYMENT_CREATE_URL;
    const PAYMENT_VERIFY_URL = window.MH.PAYMENT_VERIFY_URL;

    // Rend les icônes Lucide du markup statique (<i data-icon="...">)
    hydrateIcons();

    let supabase = null;

    // Dynamically import and initialize Supabase
    (async () => {
      try {
        const { createClient } = await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.38.0/+esm');
        supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
        supabase.auth.onAuthStateChange((event) => {
          if (event === "PASSWORD_RECOVERY") {
            openModal("#recoveryModal");
          }
        });
        initializeApp();
      } catch (err) {
        console.error("Impossible d'initialiser Supabase:", err);
        showLoaderError();
      }
    })();

