    const safeText = (val) => String(val ?? "");

    // Applique le logo importé depuis l'admin (state.settings.storeLogoUrl) au
    // <img> donné. Si aucun logo n'a encore été importé, on retire l'attribut
    // src plutôt que d'afficher une image par défaut sans rapport : le
    // pictogramme de secours (.brand-mark / .loader-logo-fallback) reste
    // visible derrière, identique sur la page de chargement et sur le site.
    function applyLogo(el, url) {
      if (!el) return;
      if (url) { el.src = url; el.style.display = ""; }
      else { el.removeAttribute("src"); el.style.display = "none"; }
    }

    // Correspondance couleur (texte libre en français) → code hexadécimal
    // pour afficher une pastille. Couleur non reconnue → pastille neutre.
    const COLOR_NAME_TO_HEX = {
      "rouge": "#e63946", "bleu": "#3b82f6", "bleu marine": "#1d3557", "noir": "#111111",
      "blanc": "#ffffff", "vert": "#22c55e", "jaune": "#eab308", "gris": "#9ca3af",
      "rose": "#ec4899", "orange": "#f97316", "violet": "#8b5cf6", "mauve": "#a78bfa",
      "marron": "#78350f", "beige": "#e8dcc8", "doré": "#d4af37", "dore": "#d4af37",
      "or": "#d4af37", "argent": "#c0c0c0", "argenté": "#c0c0c0", "turquoise": "#14b8a6",
      "bordeaux": "#7f1d1d", "kaki": "#7a7d3c", "corail": "#ff6f61", "ivoire": "#fdf6ec",
      "champagne": "#f7e7ce", "bronze": "#8c6b4f", "cuivre": "#b87333", "multicolore": "linear-gradient(90deg,#e63946,#f4a261,#2a9d8f,#457b9d)"
    };
    function colorNameToHex(name) {
      const key = (name || "").trim().toLowerCase();
      return COLOR_NAME_TO_HEX[key] || "linear-gradient(135deg,#d1d5db,#f3f4f6)";
    }

    // SHA-256 pour mot de passe
    async function sha256(val) {
      const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(val));
      return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
    }

    // Storage - Supabase integration
    async function readStore(table, fallback) {
      try {
        if (!supabase) return fallback;
        const { data, error } = await supabase.from(table).select("*");
        if (error) { console.error(`Supabase error reading ${table}:`, error); return fallback; }

        if (table === "settings" || table === "announcements" || table === "payments") {
          return data && data.length > 0 ? data[0] : fallback;
        }
        return data || fallback;
      } catch (err) {
        console.error(`Error in readStore(${table}):`, err);
        return fallback;
      }
    }

    async function writeStore(table, val) {
      try {
        if (!supabase) return;

        if (table === "settings" || table === "announcements" || table === "payments") {
          const { error } = await supabase.from(table).upsert([{ ...val, id: "main" }], { onConflict: "id" });
          if (error) console.error(`Supabase error writing to ${table}:`, error);
        } else if (Array.isArray(val)) {
          const { error } = await supabase.from(table).upsert(val, { onConflict: "id" });
          if (error) console.error(`Supabase error writing to ${table}:`, error);
        }
      } catch (err) {
        console.error("Error in writeStore:", err);
      }
    }

    // Upsert ciblé d'une seule ligne (évite d'écraser tout le tableau en mémoire
    // et donc les modifications concurrentes faites par l'admin ou d'autres clients)
    async function writeRow(table, row) {
      try {
        if (!supabase) return false;
        const { error } = await supabase.from(table).upsert([row], { onConflict: "id" });
        if (error) { console.error(`Supabase error writing row to ${table}:`, error); return false; }
        return true;
      } catch (err) {
        console.error(`Error in writeRow(${table}):`, err);
        return false;
      }
    }

    // Interroge Bazik (via l'Edge Function) pour connaître le vrai statut d'un
    // paiement. Retourne "succeeded" | "failed" | "pending" | null (erreur).
    async function verifyOrderRemote(orderId) {
      try {
        const res = await fetch(PAYMENT_VERIFY_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json", "Authorization": `Bearer ${SUPABASE_ANON_KEY}`, "apikey": SUPABASE_ANON_KEY },
          body: JSON.stringify({ orderId })
        });
        const data = await res.json();
        return data.paymentStatus || null;
      } catch { return null; }
    }

    // Annule automatiquement les commandes MonCash restées "En attente" sans
    // paiement confirmé après 30 minutes (panier abandonné / paiement jamais
    // terminé) — évite des commandes fantômes visibles indéfiniment dans
    // l'admin et le compte client.
    // SÉCURITÉ : avant d'annuler, on vérifie en direct auprès de Bazik — si le
    // client a payé puis quitté sans revenir, la commande est sauvée au lieu
    // d'être annulée alors que l'argent a été encaissé.
    async function cleanupStaleMoncashOrders() {
      const THRESHOLD_MS = 30 * 60 * 1000;
      const now = Date.now();
      const stale = state.orders.filter((o) =>
        o.paymentMethod === "MonCash" &&
        o.status === "En attente" &&
        o.paymentStatus !== "succeeded" &&
        (now - new Date(o.createdAt).getTime()) > THRESHOLD_MS
      );
      let changed = false;
      for (const o of stale) {
        // Commande passée par l'API Bazik : vérification en direct d'abord
        if (o.paymentRef || o.paymentProvider === "bazik") {
          const remote = await verifyOrderRemote(o.id);
          if (remote === "succeeded") { o.paymentStatus = "succeeded"; changed = true; continue; }
          if (remote === "pending" || remote === null) continue; // paiement encore possible — on attend
          // "failed" confirmé par Bazik → on annule proprement ci-dessous
        }
        o.status = "Annulée";
        o.paymentStatus = o.paymentStatus === "failed" ? "failed" : "cancelled";
        // Restaure le stock des articles de cette commande non payée
        for (const item of o.items || []) {
          const product = state.products.find((p) => p.id === item.id);
          if (product) {
            product.stock = Number(product.stock) + Number(item.quantity);
            await writeRow("products", product);
          }
        }
        await writeRow("orders", { id: o.id, status: "Annulée", paymentStatus: o.paymentStatus });
        changed = true;
      }
      if (changed) { renderAccountModal(); renderProductsGrid(); }
    }

    // Upload d'un fichier vers Supabase Storage et récupération de l'URL publique
    async function uploadFileToBucket(bucket, file) {
      if (!supabase || !file) return "";
      try {
        const safeName = file.name.replace(/[^a-zA-Z0-9.\-_]/g, "_");
        const path = `${Date.now()}-${safeName}`;
        const { error: uploadError } = await supabase.storage.from(bucket).upload(path, file, {
          cacheControl: "3600",
          upsert: false
        });
        if (uploadError) {
          console.error(`Erreur upload vers le bucket ${bucket}:`, uploadError);
          return "";
        }
        const { data } = supabase.storage.from(bucket).getPublicUrl(path);
        return data?.publicUrl || "";
      } catch (err) {
        console.error(`Erreur uploadFileToBucket(${bucket}):`, err);
        return "";
      }
    }

    // Local storage helpers for cart (not synced to cloud)
    function readLocalCart() {
      try { const raw = localStorage.getItem(STORAGE.cart); return raw ? JSON.parse(raw) : []; } catch { return []; }
    }
    function writeLocalCart(cart) { localStorage.setItem(STORAGE.cart, JSON.stringify(cart)); }

    // Initialisation
    async function seedData() {
      try {
        // Load products directement depuis Supabase (aucune écriture côté client)
        // Les déclinaisons ml (priceByVolume) et la galerie (imageGallery) sont
        // déjà incluses dans chaque ligne produit, aucune table séparée à charger.
        const productsData = await readStore("products", []);
        state.products = productsData || [];

        // Load settings
        const settingsData = await readStore("settings", DEFAULT_SETTINGS);
        state.settings = settingsData || DEFAULT_SETTINGS;

        // Load announcements
        const announcementsData = await readStore("announcements", DEFAULT_ANNOUNCEMENTS);
        state.announcements = announcementsData || DEFAULT_ANNOUNCEMENTS;

        // Load payments
        const paymentsData = await readStore("payments", DEFAULT_PAYMENTS);
        state.payments = normalizePayments(paymentsData);

        // Load customers
        const customersData = await readStore("customers", []);
        state.customers = customersData || [];

        // Load orders
        const ordersData = await readStore("orders", []);
        state.orders = ordersData || [];
        cleanupStaleMoncashOrders(); // en tâche de fond, ne bloque pas l'affichage

        // Load avis clients (table facultative — si elle n'existe pas encore
        // côté Supabase, readStore capture l'erreur et renvoie [] sans bloquer
        // le reste de la boutique).
        const reviewsData = await readStore("reviews", []);
        state.reviews = reviewsData || [];

        // Load cart from localStorage (local only, not synced)
        state.cart = readLocalCart();

        // Apply dynamic settings
        if (state.settings.brandColor) {
          document.documentElement.style.setProperty("--brand", state.settings.brandColor);
        }
        $("#brandName").textContent = state.settings.storeName;
        applyLogo($('#brandLogo'), state.settings.storeLogoUrl || DEFAULT_SETTINGS.storeLogoUrl);
        applyLogo($('#loaderLogo'), state.settings.storeLogoUrl || DEFAULT_SETTINGS.storeLogoUrl);
        
        renderAnnouncement();
        renderSupportBubble();
        renderFilters();
        renderProductsGrid();
        renderCartPanel();

        // Setup real-time listeners
        setupRealtimeListeners();

        // L'interface n'est révélée qu'une fois toutes les données récupérées
        revealApp();
        handleMoncashReturn();
        handleSharedProductLink();
      } catch (err) {
        console.error("Error in seedData:", err);
        // On révèle quand même l'app (avec un catalogue vide) plutôt que de
        // laisser l'utilisateur bloqué indéfiniment sur le loader.
        revealApp();
      }
    }

    // Gère le retour du client depuis la page de paiement MonCash (Bazik),
    // via returnUrl/cancelUrl (?paiement=succes|annule&commande=ID). On
    // interroge Bazik en direct via l'Edge Function bazik-verify-payment,
    // puis on relit notre propre table jusqu'à confirmation — on ne se fie
    // jamais au seul retour navigateur pour valider un paiement.
    // Ouvre automatiquement la fiche produit quand un client arrive via un lien
    // partagé (?produit=ID généré par le bouton "Partager" de la fiche produit).
    function handleSharedProductLink() {
      const params = new URLSearchParams(window.location.search);
      const productId = params.get("produit");
      if (!productId) return;
      window.history.replaceState({}, "", window.location.pathname);
      if (state.products.some((p) => p.id === productId)) {
        renderProductDetailModal(productId);
        openModal("#productDetailModal");
      }
    }

    async function handleMoncashReturn() {
      const params = new URLSearchParams(window.location.search);
      const paiement = params.get("paiement");
      const commande = params.get("commande");
      if (!paiement || !commande) return;

      // Nettoie l'URL tout de suite pour éviter un re-déclenchement au refresh
      window.history.replaceState({}, "", window.location.pathname);

      if (paiement === "annule") {
        alert(`Paiement annulé pour la commande ${commande}. Le panier a été vidé au moment du paiement : ajoutez à nouveau vos articles pour réessayer.`);
        return;
      }

      if (paiement === "succes") {
        const banner = document.createElement("div");
        banner.id = "moncashStatusBanner";
        banner.style.cssText = "position:fixed;top:14px;left:50%;transform:translateX(-50%);z-index:200;background:var(--surface2);border:1px solid var(--border);border-radius:999px;padding:10px 20px;box-shadow:var(--shadow-lg);font-weight:700;font-size:13.5px;display:inline-flex;align-items:center;gap:8px;";
        banner.innerHTML = `${icon('loader-circle','spin')} Vérification du paiement de la commande ${commande}...`;
        document.body.appendChild(banner);

        // Vérification EN DIRECT auprès de Bazik via l'Edge Function : interroge
        // api.bazik.io/order/{id} et met à jour orders.paymentStatus. En cas
        // d'échec réseau, on retombe sur le polling de notre propre table.
        try {
          await fetch(PAYMENT_VERIFY_URL, {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${SUPABASE_ANON_KEY}`, "apikey": SUPABASE_ANON_KEY },
            body: JSON.stringify({ orderId: commande })
          });
        } catch { /* le polling ci-dessous prend le relais */ }

        const deadline = Date.now() + 60000; // 60s de tolérance pour la confirmation
        (async function poll() {
          try {
            const res = await fetch(`${SUPABASE_URL}/rest/v1/orders?id=eq.${encodeURIComponent(commande)}&select=paymentStatus`, {
              headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${SUPABASE_ANON_KEY}` }
            });
            const rows = await res.json();
            const paymentStatus = rows?.[0]?.paymentStatus;

            if (paymentStatus === "succeeded") {
              banner.innerHTML = `${icon('circle-check','','color:var(--success);')} Paiement confirmé — commande ${commande} validée !`;
              setTimeout(() => banner.remove(), 6000);
              return;
            }
            if (paymentStatus === "failed") {
              banner.innerHTML = `${icon('circle-x','','color:var(--danger);')} Le paiement a échoué pour la commande ${commande}.`;
              setTimeout(() => banner.remove(), 8000);
              return;
            }
            if (Date.now() < deadline) {
              setTimeout(poll, 3000);
            } else {
              banner.innerHTML = `${icon('clock')} Confirmation en cours pour la commande ${commande} — vérifiez votre compte dans quelques minutes.`;
              setTimeout(() => banner.remove(), 8000);
            }
          } catch {
            banner.remove();
          }
        })();
      }
    }

    let realtimeInitialized = false;

    function setupRealtimeListeners() {
      if (!supabase || realtimeInitialized) return;
      realtimeInitialized = true;

      // Écoute des changements sur les produits (stock/prix en direct)
      supabase
        .channel('public:products:store')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, async () => {
          const productsData = await readStore("products", []);
          state.products = productsData || [];
          renderFilters();
          renderProductsGrid();
        })
        .subscribe();

      // Écoute des changements sur les paramètres (couleur de marque, logo, nom de boutique)
      supabase
        .channel('public:settings:store')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'settings' }, async () => {
          const settingsData = await readStore("settings", DEFAULT_SETTINGS);
          state.settings = settingsData || DEFAULT_SETTINGS;
          if (state.settings.brandColor) {
            document.documentElement.style.setProperty("--brand", state.settings.brandColor);
          }
          $("#brandName").textContent = state.settings.storeName;
          applyLogo($('#brandLogo'), state.settings.storeLogoUrl || DEFAULT_SETTINGS.storeLogoUrl);
        applyLogo($('#loaderLogo'), state.settings.storeLogoUrl || DEFAULT_SETTINGS.storeLogoUrl);
          renderSupportBubble();
        })
        .subscribe();

      // Écoute des changements sur le bandeau d'annonce
      supabase
        .channel('public:announcements:store')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'announcements' }, async () => {
          const announcementsData = await readStore("announcements", DEFAULT_ANNOUNCEMENTS);
          state.announcements = announcementsData || DEFAULT_ANNOUNCEMENTS;
          renderAnnouncement();
        })
        .subscribe();

      // Écoute des changements sur les méthodes de paiement (numéros MonCash/NatCash/banque)
      supabase
        .channel('public:payments:store')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'payments' }, async () => {
          const paymentsData = await readStore("payments", DEFAULT_PAYMENTS);
          state.payments = normalizePayments(paymentsData);
        })
        .subscribe();
    }

    function initializeApp() {
      seedData();
    }

    function currentCustomer() {
      const session = localStorage.getItem(STORAGE.session);
      if (!session) return null;
      return state.customers.find((c) => c.id === session) || null;
    }

    function renderProductsGrid() {
      // Un produit désactivé côté admin (isActive = false) reste en base mais
      // n'est jamais visible côté client.
      let products = state.products.filter((p) => p.isActive !== false);

      // Filtrages
      if (state.filters.category) products = products.filter((p) => p.category === state.filters.category);
      if (state.filters.vendor) products = products.filter((p) => p.vendorName === state.filters.vendor);
      if (state.filters.search) {
        const search = state.filters.search.toLowerCase();
        products = products.filter((p) => p.name.toLowerCase().includes(search) || p.vendorName.toLowerCase().includes(search));
      }
      if (state.filters.priceMin != null) products = products.filter((p) => Number(p.price) >= state.filters.priceMin);
      if (state.filters.priceMax != null) products = products.filter((p) => Number(p.price) <= state.filters.priceMax);
      if (state.filters.minRating) products = products.filter((p) => avgRating(p.id).avg >= state.filters.minRating);

      // Tri
      switch (state.filters.sort) {
        case "priceAsc": products = products.sort((a, b) => a.price - b.price); break;
        case "priceDesc": products = products.sort((a, b) => b.price - a.price); break;
        case "stockAsc": products = products.sort((a, b) => a.stock - b.stock); break;
        case "nameAsc": products = products.sort((a, b) => a.name.localeCompare(b.name)); break;
        case "ratingDesc": products = products.sort((a, b) => avgRating(b.id).avg - avgRating(a.id).avg); break;
      }

      $("#resultSummary").textContent = products.length > 0 ? `${products.length} produit(s) disponible(s)` : "Aucun résultat";

      if (products.length === 0) {
        $("#productsGrid").innerHTML = "";
        $("#emptyProducts").hidden = false;
        return;
      }

      $("#emptyProducts").hidden = true;
      const LOW_STOCK_THRESHOLD = 5;
      $("#productsGrid").innerHTML = products.map((p) => {
        const hasVariants = (Array.isArray(p.priceByVolume) && p.priceByVolume.length > 0) || (Array.isArray(p.colorOptions) && p.colorOptions.length > 0);
        const hasPromo = p.compareAtPrice && Number(p.compareAtPrice) > Number(p.price);
        const discountPct = hasPromo ? Math.round((1 - Number(p.price) / Number(p.compareAtPrice)) * 100) : 0;
        let stockLine = "";
        if (p.stock <= 0) stockLine = `<p class="product-stock low">Rupture de stock</p>`;
        else if (p.stock <= LOW_STOCK_THRESHOLD) stockLine = `<p class="product-stock low">Il n'en reste que ${p.stock} !</p>`;
        return `
        <div class="product-card">
          <div class="product-image-wrap" data-open-product="${p.id}" role="button" tabindex="0">
            ${hasPromo ? `<span class="promo-badge">-${discountPct}%</span>` : ""}
            ${p.imageUrl ? `<img src="${safeText(p.imageUrl)}" alt="${safeText(p.name)}">` : `<div class="image-fallback">${icon('image')}</div>`}
          </div>
          <div class="product-info">
            <div class="product-top">
              <div class="product-vendor">
                ${p.vendorLogo ? `<img src="${safeText(p.vendorLogo)}" alt="" class="vendor-logo">` : ""}
                <span>${safeText(p.vendorName)}</span>
              </div>
              <h3 class="product-name" data-open-product="${p.id}" role="button" tabindex="0">${safeText(p.name)}</h3>
              <div class="product-rating">${avgRating(p.id).count ? `${starsHtml(avgRating(p.id).avg)} <span>(${avgRating(p.id).count})</span>` : `<span class="no-rating">Pas encore d'avis</span>`}</div>
            </div>
            <div class="product-price-row">
              <span>${hasPromo ? `<span class="product-compare-price">${money(p.compareAtPrice)}</span>` : ""}<span class="product-price">${money(p.price)}</span></span>
              <button class="add-to-cart" type="button" ${hasVariants ? `data-open-product="${p.id}"` : `data-add-to-cart="${p.id}"`} ${p.stock <= 0 ? "disabled" : ""} title="${hasVariants ? 'Choisir une déclinaison' : 'Ajouter au panier'}">${icon(hasVariants ? 'eye' : 'plus')}</button>
            </div>
            ${stockLine}
          </div>
        </div>
      `;
      }).join("");
    }

    function renderCartPanel() {
      const items = state.cart;
      $("#cartBadge").textContent = items.length;

      if (items.length === 0) {
        $("#cartItems").innerHTML = `<p class="muted" style="padding:20px;text-align:center;">Votre panier est vide</p>`;
        $("#checkoutBtn").disabled = true;
        return;
      }

      $("#cartItems").innerHTML = items.map((item) => `
        <div class="cart-item">
          <img src="${safeText(item.imageUrl)}" alt="">
          <div>
            <div class="cart-item-name">${safeText(item.name)}${item.variantLabel ? ` <span class="muted" style="font-weight:600;">(${safeText(item.variantLabel)})</span>` : ""}</div>
            <div class="cart-item-vendor">${safeText(item.vendorName)}</div>
            <div class="cart-item-price">${money(item.price)}</div>
            <div class="qty-row">
              <div class="qty-control">
                <button class="qty-btn" type="button" data-qty-minus="${item.cartLineId}">−</button>
                <span>${item.quantity}</span>
                <button class="qty-btn" type="button" data-qty-plus="${item.cartLineId}">+</button>
              </div>
              <button class="remove-btn" type="button" data-remove-item="${item.cartLineId}">Supprimer</button>
            </div>
          </div>
        </div>
      `).join("");

      const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
      $("#cartTotal").textContent = money(total);
      $("#checkoutBtn").disabled = false;
    }

    function renderAnnouncement() {
      const banner = $("#announcementBanner");
      if (!banner) return;
      if (state.announcements.active && state.announcements.message) {
        const textColor = state.announcements.textColor || DEFAULT_ANNOUNCEMENTS.textColor;
        banner.innerHTML = `<span class="announce-bar__text" style="color: ${textColor};">${state.announcements.message}</span>`;
        banner.hidden = false;
      } else {
        banner.hidden = true;
      }
    }

    function renderSupportBubble() {
      const bubble = $("#supportBubble");
      if (!bubble) return;

      const supportPhone = (state.settings.supportPhone || DEFAULT_SETTINGS.supportPhone || "+50941641700").replace(/\D/g, "");
      const message = `Bonjour, je souhaite obtenir de l'aide pour ma commande chez ${state.settings.storeName || DEFAULT_SETTINGS.storeName}.`;
      const whatsappUrl = `https://wa.me/${supportPhone}?text=${encodeURIComponent(message)}`;

      bubble.innerHTML = `
        <a href="${whatsappUrl}" target="_blank" rel="noopener noreferrer" class="support-link">
          <span class="support-icon">${icon('whatsapp')}</span>
          <span class="support-content">
            <strong>Besoin d'aide ?</strong>
            <small>Contactez-nous sur WhatsApp</small>
          </span>
        </a>
      `;
    }

    function renderAccountModal() {
      const customer = currentCustomer();

      // ----- Mode "mot de passe oublié" -----
      if (!customer && state.authMode === "forgot") {
        $("#accountContent").innerHTML = `
          <h3 style="margin-bottom:10px;">Mot de passe oublié</h3>
          <p class="muted" style="margin-bottom:16px;">Entrez le téléphone ou le nom d'utilisateur de votre compte. Un lien de réinitialisation sera envoyé à l'adresse email associée.</p>
          <form id="forgotForm" class="form-grid">
            <div class="field full"><label for="forgotCredential">Téléphone ou nom d'utilisateur</label><input id="forgotCredential" type="text" required placeholder="+509... ou @james25"></div>
            <div class="field full"><button class="btn-primary" type="submit">${icon('send')} Envoyer le lien</button></div>
            <p id="forgotError" class="error-text"></p>
            <p id="forgotSuccess" class="muted" style="color:var(--success);font-weight:700;"></p>
            <div class="field full"><button class="btn-soft" type="button" data-auth-type="signin">← Retour à la connexion</button></div>
          </form>
        `;
        setTimeout(() => {
          $$('[data-auth-type]').forEach((btn) => btn.addEventListener("click", () => { state.authMode = btn.dataset.authType; renderAccountModal(); }));
          $("#forgotForm").addEventListener("submit", async (e) => {
            e.preventDefault();
            const credential = $("#forgotCredential").value.trim();
            const match = state.customers.find((c) => c.phone === credential || c.username === credential);
            $("#forgotError").textContent = "";
            $("#forgotSuccess").textContent = "";
            if (!match) {
              $("#forgotError").textContent = "Aucun compte trouvé avec ces informations.";
              return;
            }
            if (!match.email) {
              $("#forgotError").textContent = "Aucun email n'est associé à ce compte. Contactez le support via la bulle WhatsApp pour réinitialiser votre mot de passe.";
              return;
            }
            const submitBtn = $("#forgotForm button[type='submit']");
            if (submitBtn) { submitBtn.disabled = true; }
            const ok = await sendPasswordResetEmail(match.email);
            if (submitBtn) { submitBtn.disabled = false; }
            if (ok) {
              $("#forgotSuccess").textContent = `Un lien de réinitialisation a été envoyé à ${match.email}. Vérifiez votre boîte de réception (et les spams).`;
            } else {
              $("#forgotError").textContent = "Échec de l'envoi. Réessayez dans quelques instants.";
            }
          });
        }, 0);
        return;
      }

      // ----- Mode "inscription vendeur" -----
      // Crée directement un compte vendeur en base (status "pending") — le
      // vendeur pourra ensuite se connecter sur vendor.html une fois validé
      // par l'admin. Le numéro WhatsApp reste affiché pour le support.
      if (!customer && state.authMode === "vendor") {
        const categoryOptions = MARKET_CATEGORIES.map((c) => `<option value="${safeText(c.name)}">${safeText(c.name)}</option>`).join("");
        $("#accountContent").innerHTML = `
          <h3 style="margin-bottom:6px;">Devenir vendeur</h3>
          <p class="muted" style="margin-bottom:16px;">Créez votre compte vendeur : après validation par notre équipe, vous pourrez publier vos produits et suivre vos ventes depuis votre espace.</p>
          <form id="vendorForm" class="form-grid">
            <div class="field full"><label for="vendorShopName">Nom de la boutique</label><input id="vendorShopName" type="text" required placeholder="Ex: James Shop"></div>
            <div class="field"><label for="vendorLastName">Nom</label><input id="vendorLastName" type="text" required placeholder="Pierre"></div>
            <div class="field"><label for="vendorFirstName">Prénom</label><input id="vendorFirstName" type="text" required placeholder="James"></div>
            <div class="field"><label for="vendorPhone">Téléphone</label><input id="vendorPhone" type="tel" required placeholder="+509..."></div>
            <div class="field"><label for="vendorEmail">Email</label><input id="vendorEmail" type="email" required placeholder="boutique@example.com"></div>
            <div class="field full"><label for="vendorAddress">Adresse</label><input id="vendorAddress" type="text" required placeholder="Rue, ville, département"></div>
            <div class="field full"><label for="vendorCategory">Catégorie de produits</label><select id="vendorCategory" required><option value="" disabled selected>Choisir une catégorie</option>${categoryOptions}</select></div>
            <div class="field full"><label for="vendorPassword">Mot de passe</label><input id="vendorPassword" type="password" required minlength="6" placeholder="Minimum 6 caractères"></div>
            <div class="field full"><button class="btn-primary" type="submit">${icon('store')} Créer mon compte vendeur</button></div>
            <p id="vendorError" class="error-text"></p>
            <p id="vendorSuccess" class="muted" style="color:var(--success);font-weight:700;"></p>
            <div class="field full"><button type="button" class="btn-soft" data-auth-type="signin">← Retour</button></div>
          </form>
          <p class="muted" style="margin-top:10px;font-size:12.5px;">Déjà vendeur ? <a href="vendor.html" style="color:var(--brand);font-weight:700;">Connectez-vous à votre espace</a>.</p>
        `;
        setTimeout(() => {
          $$('[data-auth-type]').forEach((btn) => btn.addEventListener("click", () => { state.authMode = btn.dataset.authType; renderAccountModal(); }));
          $("#vendorForm").addEventListener("submit", async (e) => {
            e.preventDefault();
            const shopName = $("#vendorShopName").value.trim();
            const ownerName = `${$("#vendorFirstName").value.trim()} ${$("#vendorLastName").value.trim()}`.trim();
            const phone = $("#vendorPhone").value.trim();
            const email = $("#vendorEmail").value.trim().toLowerCase();
            const address = $("#vendorAddress").value.trim();
            const category = $("#vendorCategory").value;
            const password = $("#vendorPassword").value;
            $("#vendorError").textContent = "";
            $("#vendorSuccess").textContent = "";
            if (password.length < 6) {
              $("#vendorError").textContent = "Le mot de passe doit contenir au moins 6 caractères.";
              return;
            }
            const submitBtn = e.target.querySelector("button[type='submit']");
            submitBtn.disabled = true;
            const vendors = await readStore("vendors", []);
            const duplicate = (vendors || []).find((v) => (v.email || "").toLowerCase() === email || v.phone === phone);
            if (duplicate) {
              $("#vendorError").textContent = duplicate.status === "pending"
                ? "Un compte existe déjà avec ces coordonnées et est en attente de validation."
                : "Un compte vendeur existe déjà avec cet email ou ce téléphone — connectez-vous sur l'espace vendeur.";
              submitBtn.disabled = false;
              return;
            }
            const vendor = {
              id: uid("vend"),
              name: shopName,
              ownerName,
              phone, email, address, category,
              passwordHash: await sha256(password),
              commission: null,          // l'admin fixe sa part (sinon le global s'applique)
              dueBalance: 0,
              paymentMethod: "MonCash",
              paymentDetails: "",
              logo: "",
              status: "pending",
              createdAt: new Date().toISOString()
            };
            const ok = await writeRow("vendors", vendor);
            submitBtn.disabled = false;
            if (!ok) {
              $("#vendorError").textContent = "Erreur lors de la création du compte. Réessayez dans un instant.";
              return;
            }
            $("#vendorSuccess").textContent = "Compte créé ! Il est en attente de validation par notre équipe — vous pourrez ensuite vous connecter sur l'espace vendeur (lien ci-dessous).";
            e.target.reset();
          });
        }, 0);
        return;
      }

      if (!customer) {
        $("#accountContent").innerHTML = `
          <div class="auth-tabs">
            <button class="auth-tab ${state.authMode === "signin" ? "active" : ""}" type="button" data-auth-type="signin">Se connecter</button>
            <button class="auth-tab ${state.authMode === "signup" ? "active" : ""}" type="button" data-auth-type="signup">S'inscrire</button>
          </div>
          <form id="authForm" class="form-grid">
            ${state.authMode === "signup" ? `<div class="field full"><label for="authName">Nom complet</label><input id="authName" type="text" required placeholder="James Pierre"></div><div class="field full"><label for="authUsername">Nom d'utilisateur</label><input id="authUsername" type="text" required placeholder="@james25"></div><div class="field full"><label for="authEmail">Email</label><input id="authEmail" type="email" required placeholder="james@example.com"></div>` : ``}
            <div class="field full"><label for="authCredential">${state.authMode === "signin" ? "Téléphone ou nom d'utilisateur" : "Téléphone"}</label><input id="authCredential" type="text" required placeholder="${state.authMode === "signin" ? "+509... ou @james25" : "+509..."}"></div>
            <div class="field full"><label for="authPassword">Mot de passe</label><input id="authPassword" type="password" required placeholder="Mot de passe sécurisé"></div>
            <div class="field full"><button class="btn-primary" type="submit">${icon('log-in')} ${state.authMode === "signin" ? "Connexion" : "Créer un compte"}</button></div>
            ${state.authMode === "signin" ? `<div class="field full" style="text-align:right;margin-top:-8px;"><button type="button" class="remove-btn" style="color:var(--brand);" data-auth-type="forgot">Mot de passe oublié ?</button></div>` : ``}
            <p id="authError" class="error-text"></p>
          </form>
          <p class="muted" style="text-align:center;margin-top:16px;font-size:13px;">Vous êtes vendeur ? <button type="button" class="link-btn" data-auth-type="vendor">Rejoignez-nous ici</button></p>
        `;
        setTimeout(() => {
          $$('[data-auth-type]').forEach((btn) => {
            btn.addEventListener("click", () => {
              state.authMode = btn.dataset.authType;
              renderAccountModal();
            });
          });

          $("#authForm").addEventListener("submit", async (e) => {
            e.preventDefault();
            const credential = $("#authCredential").value.trim();
            const password = $("#authPassword").value.trim();
            const passwordHash = await sha256(password);

            if (state.authMode === "signin") {
              const customer = state.customers.find((c) => (c.phone === credential || c.username === credential) && c.passwordHash === passwordHash);
              if (customer) {
                localStorage.setItem(STORAGE.session, customer.id);
                renderAccountModal();
                openModal("#accountModal");
              } else {
                $("#authError").textContent = "Téléphone/username ou mot de passe incorrect.";
              }
            } else {
              const username = $("#authUsername").value.trim().replace(/^@/, "");
              const name = $("#authName").value.trim();
              const email = $("#authEmail").value.trim().toLowerCase();
              if (!name || !username || !email) {
                $("#authError").textContent = "Nom complet, nom d'utilisateur et email sont requis.";
                return;
              }
              if (state.customers.find((c) => c.phone === credential)) {
                $("#authError").textContent = "Ce téléphone est déjà inscrit.";
                return;
              }
              if (state.customers.find((c) => c.username?.toLowerCase() === username.toLowerCase())) {
                $("#authError").textContent = "Ce nom d'utilisateur est déjà pris.";
                return;
              }
              if (state.customers.find((c) => c.email?.toLowerCase() === email)) {
                $("#authError").textContent = "Cet email est déjà utilisé par un autre compte.";
                return;
              }
              // Compte Supabase Auth (permet l'envoi du lien "mot de passe oublié" plus tard).
              // Le mot de passe reste vérifié via passwordHash pour ne rien casser côté existant.
              if (supabase) {
                const { error: authError } = await supabase.auth.signUp({ email, password });
                if (authError && !/already registered/i.test(authError.message || "")) {
                  console.error("Erreur création compte Supabase Auth:", authError);
                }
              }
              const newCustomer = { id: uid("cust"), name, username, phone: credential, email, passwordHash, registeredAt: new Date().toISOString() };
              state.customers.push(newCustomer);
              await writeStore("customers", state.customers);
              localStorage.setItem(STORAGE.session, newCustomer.id);
              renderAccountModal();
              openModal("#accountModal");
            }
          });
        }, 0);
      } else {
        const section = state.accountSection || "info";
        const initial = (customer.name || "?").trim().charAt(0).toUpperCase();

        const infoPanel = `
          <div class="account-info-row"><span class="account-info-label">Nom complet</span><span class="account-info-value">${safeText(customer.name)}</span></div>
          <div class="account-info-row"><span class="account-info-label">Nom d'utilisateur</span><span class="account-info-value">${safeText(customer.username ? '@' + customer.username : "—")}</span></div>
          <div class="account-info-row"><span class="account-info-label">Téléphone</span><span class="account-info-value">${safeText(customer.phone)}</span></div>
          <div class="account-info-row"><span class="account-info-label">Membre depuis</span><span class="account-info-value">${new Date(customer.registeredAt).toLocaleDateString("fr-FR")}</span></div>
          ${customer.email ? `<div class="account-info-row"><span class="account-info-label">Email</span><span class="account-info-value">${safeText(customer.email)}</span></div>` : ""}
          ${!customer.email ? `
            <div class="field full" style="margin-top:16px;">
              <label for="profileEmail">Ajouter un email (utilisé pour la récupération du mot de passe)</label>
              <div style="display:flex;gap:8px;">
                <input id="profileEmail" type="email" placeholder="votre@email.com" style="flex:1;border:1.5px solid var(--border);border-radius:10px;padding:12px;">
                <button class="btn-soft" type="button" id="saveEmailBtn">Enregistrer</button>
              </div>
              <p id="emailSaveMsg" class="muted" style="font-size:12px;"></p>
            </div>
          ` : ""}
        `;

        const orders = state.orders.filter((o) => o.customerId === customer.id);
        const ordersPanel = orders.map((o) => {
          let statusClass = "";
          if (o.status === "En attente") statusClass = "pending";
          else if (o.status === "Validée") statusClass = "validated";
          else if (o.status === "En livraison") statusClass = "shipping";
          else if (o.status === "Livrée") statusClass = "delivered";
          else if (o.status === "Annulée") statusClass = "cancelled";
          const paymentBadges = { pending: ["Paiement en attente", "payment-pending"], succeeded: ["Payé", "payment-succeeded"], failed: ["Paiement échoué", "payment-failed"], cancelled: ["Paiement annulé", "payment-cancelled"] };
          const [payLabel, payClass] = paymentBadges[o.paymentStatus] || paymentBadges.pending;
          return `
          <div class="order-card">
            <div><strong>Commande #${safeText(o.id)}</strong></div>
            <div class="muted">${new Date(o.createdAt).toLocaleString("fr-FR")} - ${money(o.total)}</div>
            <div style="display:flex;gap:6px;flex-wrap:wrap;"><span class="status-pill ${statusClass}">${safeText(o.status)}</span>${o.paymentMethod === "MonCash" ? `<span class="status-pill ${payClass}">${payLabel}</span>` : ""}${o.paymentMethod === "MonCash" && o.paymentStatus !== "succeeded" && o.status === "En attente" ? `<button type="button" class="btn-soft" style="padding:4px 10px;font-size:12px;" data-verify-payment="${safeText(o.id)}">${icon('refresh-cw')} Vérifier le paiement</button>` : ""}</div>
            <div style="font-size:12px;">${o.items.map((i) => `${safeText(i.name)}${i.variantLabel ? ' (' + safeText(i.variantLabel) + ')' : ''} x${i.quantity}`).join(", ")}</div>
          </div>
        `}).join("") || `<p class="muted">Aucune commande pour le moment.</p>`;

        $("#accountContent").innerHTML = `
          <div class="account-header">
            <div class="account-avatar">${safeText(initial)}</div>
            <div>
              <h3 style="margin-bottom:2px;">${safeText(customer.name)}</h3>
              <p class="muted">${safeText(customer.username ? '@' + customer.username : customer.phone)}</p>
            </div>
          </div>
          <div class="account-menu">
            <button type="button" class="account-menu-btn ${section === "info" ? "active" : ""}" data-account-section="info">${icon('circle-user')} Infos du compte</button>
            <button type="button" class="account-menu-btn ${section === "orders" ? "active" : ""}" data-account-section="orders">${icon('package')} Historique</button>
            <button type="button" class="account-menu-btn danger" id="logoutBtn">${icon('log-out')} Déconnexion</button>
          </div>
          <div>${section === "orders" ? ordersPanel : infoPanel}</div>
        `;

        // Vérification silencieuse en arrière-plan des paiements MonCash encore
        // "en attente" du client (une fois par commande et par session) —
        // couvre le cas où il a payé puis quitté la page MonCash sans revenir.
        state.orders
          .filter((o) => o.customerId === customer.id && o.paymentMethod === "MonCash" && o.status === "En attente" && o.paymentStatus !== "succeeded" && o.paymentStatus !== "failed" && !verifiedPaymentIds.has(o.id))
          .forEach(async (o) => {
            verifiedPaymentIds.add(o.id);
            const remote = await verifyOrderRemote(o.id);
            if (remote && remote !== o.paymentStatus) {
              o.paymentStatus = remote;
              if (state.accountSection === "orders") renderAccountModal();
            }
          });
        setTimeout(() => {
          $$('[data-account-section]').forEach((btn) => {
            btn.addEventListener("click", () => {
              state.accountSection = btn.dataset.accountSection;
              renderAccountModal();
            });
          });
          $("#logoutBtn")?.addEventListener("click", () => {
            localStorage.removeItem(STORAGE.session);
            state.accountSection = "info";
            renderAccountModal();
            openModal("#accountModal");
          });
          $("#saveEmailBtn")?.addEventListener("click", async () => {
            const email = $("#profileEmail").value.trim().toLowerCase();
            const msg = $("#emailSaveMsg");
            if (!email) { msg.textContent = "Veuillez saisir un email valide."; msg.style.color = "var(--danger)"; return; }
            if (state.customers.find((c) => c.email?.toLowerCase() === email && c.id !== customer.id)) {
              msg.textContent = "Cet email est déjà utilisé par un autre compte."; msg.style.color = "var(--danger)"; return;
            }
            customer.email = email;
            await writeRow("customers", customer);
            renderAccountModal();
          });
        }, 0);
      }
    }

    // Envoie l'email de réinitialisation via Supabase Auth. Si l'email n'a
    // pas encore de compte Auth associé (ancien client, ou client qui a
    // ajouté son email après coup), on en crée un silencieusement avec un
    // mot de passe aléatoire — sinon Supabase n'enverrait jamais le lien
    // (resetPasswordForEmail ignore silencieusement les emails inconnus).
    async function sendPasswordResetEmail(email) {
      if (!supabase) return false;
      try {
        // Garantit l'existence d'un compte Auth pour cet email
        const { error: signUpError } = await supabase.auth.signUp({
          email,
          password: `tmp-${crypto.randomUUID()}`
        });
        if (signUpError && !/already registered|already been registered/i.test(signUpError.message || "")) {
          console.error("Erreur création compte Auth de secours:", signUpError);
        }
        const redirectTo = window.location.origin + window.location.pathname + "?recovery=1";
        const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo });
        if (error) { console.error("Erreur resetPasswordForEmail:", error); return false; }
        return true;
      } catch (err) {
        console.error("Erreur sendPasswordResetEmail:", err);
        return false;
      }
    }

    // ===== FICHE PRODUIT : galerie + couleurs + grille de prix par ml =====
    function renderProductDetailModal(productId) {
      const p = state.products.find((pp) => pp.id === productId);
      if (!p) return;
      const volumes = Array.isArray(p.priceByVolume) ? p.priceByVolume : [];
      const colors = Array.isArray(p.colorOptions) ? p.colorOptions.filter(Boolean) : [];

      // Sélection par défaut : on garde la sélection en cours si on ré-affiche
      // la même fiche (ex: après un événement realtime), sinon 1res valeurs.
      if (state.productDetail.productId !== productId) {
        state.productDetail = { productId, activeImage: p.imageUrl || "", selectedMl: volumes[0]?.ml || "", selectedColor: colors[0] || "", reviewRating: 0 };
      }
      if (!state.productDetail.selectedMl && volumes.length) state.productDetail.selectedMl = volumes[0].ml;
      if (!state.productDetail.selectedColor && colors.length) state.productDetail.selectedColor = colors[0];

      const gallery = [p.imageUrl, ...(Array.isArray(p.imageGallery) ? p.imageGallery : [])].filter(Boolean);
      const activeImg = state.productDetail.activeImage || gallery[0] || "";
      const selectedVolume = volumes.find((v) => v.ml === state.productDetail.selectedMl) || null;
      const effectivePrice = selectedVolume && selectedVolume.price != null ? selectedVolume.price : p.price;
      const effectiveStock = Number(p.stock); // le stock reste au niveau du produit (pas de stock séparé par ml/couleur)

      $("#pdTitle").textContent = p.name;

      // La couleur n'est affichée en texte statique que si aucune liste de
      // couleurs sélectionnables n'existe (ancien champ simple, produits
      // enregistrés avant l'ajout du sélecteur graphique).
      const specsHtml = (p.brand || (!colors.length && p.color) || p.ram || p.rom || p.condition) ? `<div class="pd-specs">
          ${p.brand ? `<div class="pd-spec"><strong>Marque</strong>${safeText(p.brand)}</div>` : ""}
          ${(!colors.length && p.color) ? `<div class="pd-spec"><strong>Couleur</strong>${safeText(p.color)}</div>` : ""}
          ${p.ram ? `<div class="pd-spec"><strong>RAM</strong>${safeText(p.ram)}</div>` : ""}
          ${p.rom ? `<div class="pd-spec"><strong>ROM</strong>${safeText(p.rom)}</div>` : ""}
          ${p.condition ? `<div class="pd-spec"><strong>État</strong>${safeText(p.condition)}</div>` : ""}
        </div>` : "";

      let colorHtml = "";
      if (colors.length) {
        colorHtml = `
          <div class="pd-variant-group">
            <label>Couleur${state.productDetail.selectedColor ? ` — ${safeText(state.productDetail.selectedColor)}` : ""}</label>
            <div class="pd-color-swatches">
              ${colors.map((c) => `
                <button type="button" class="pd-color-swatch ${c === state.productDetail.selectedColor ? "active" : ""}" data-select-color="${safeText(c)}" title="${safeText(c)}">
                  <span class="pd-color-dot" style="background:${colorNameToHex(c)};"></span>
                  <span>${safeText(c)}</span>
                </button>
              `).join("")}
            </div>
          </div>`;
      }

      let variantHtml = "";
      if (volumes.length) {
        variantHtml = `
          <div class="pd-variant-group">
            <label>Contenance</label>
            <div class="pd-variant-options">
              ${volumes.map((v) => `
                <button type="button" class="pd-variant-chip ${v.ml === state.productDetail.selectedMl ? "active" : ""}" data-select-ml="${safeText(v.ml)}">
                  ${safeText(v.ml)}
                </button>
              `).join("")}
            </div>
          </div>`;
      }

      const ratingInfo = avgRating(p.id);
      const reviews = productReviews(p.id).slice().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
      const customer = currentCustomer();

      // Produits similaires : d'abord même catégorie, puis affiné par "famille" détectée
      // par mots-clés (ex: un spray ne doit suggérer que parfums/sprays, jamais des bijoux),
      // même si la catégorie du site a été choisie de façon trop large.
      const otherActive = state.products.filter((pp) => pp.isActive !== false && pp.id !== p.id);
      const pFamilies = getProductFamilies(p);
      let similar = otherActive.filter((pp) => pp.category === p.category);
      if (pFamilies.length) {
        similar = similar.filter((pp) => getProductFamilies(pp).some((f) => pFamilies.includes(f)));
        if (similar.length < 4) {
          const extra = otherActive.filter((pp) => !similar.includes(pp) && getProductFamilies(pp).some((f) => pFamilies.includes(f)));
          similar = similar.concat(extra);
        }
      }
      similar = similar.slice(0, 4);

      $("#productDetailContent").innerHTML = `
        <div class="pd-layout">
          <div>
            <div class="pd-main-image">${activeImg ? `<img src="${safeText(activeImg)}" alt="${safeText(p.name)}">` : `<div class="image-fallback">${icon('image')}</div>`}</div>
            ${gallery.length > 1 ? `<div class="pd-thumbs">${gallery.map((img) => `<button type="button" class="pd-thumb ${img === activeImg ? "active" : ""}" data-select-image="${safeText(img)}"><img src="${safeText(img)}" alt=""></button>`).join("")}</div>` : ""}
          </div>
          <div>
            <div class="pd-header-row">
              <div class="pd-vendor">${safeText(p.vendorName)}</div>
              <div class="share-wrap">
                <button class="btn-soft" type="button" id="pdShareBtn" title="Partager ce produit">${icon('share-2')} Partager</button>
                <div class="share-menu" id="pdShareMenu" hidden>
                  <button type="button" class="share-menu-item" data-share-channel="whatsapp">${icon('whatsapp')} WhatsApp</button>
                  <button type="button" class="share-menu-item" data-share-channel="facebook">${icon('facebook')} Facebook</button>
                  <button type="button" class="share-menu-item" data-share-channel="messenger">${icon('messenger')} Messenger</button>
                  <button type="button" class="share-menu-item" data-share-channel="twitter">${icon('x-twitter')} X (Twitter)</button>
                  <button type="button" class="share-menu-item" data-share-channel="telegram">${icon('telegram')} Telegram</button>
                  <button type="button" class="share-menu-item" data-share-channel="copy">${icon('copy')} Copier le lien</button>
                </div>
              </div>
            </div>
            <h2 class="pd-name">${safeText(p.name)}</h2>
            <div class="pd-rating-summary">${ratingInfo.count ? `${starsHtml(ratingInfo.avg)} <span>${ratingInfo.avg.toFixed(1)} · ${ratingInfo.count} avis</span>` : `<span>Pas encore d'avis</span>`}</div>
            <div class="pd-price" id="pdPrice">${(p.compareAtPrice && Number(p.compareAtPrice) > Number(p.price) && effectivePrice === Number(p.price)) ? `<span class="product-compare-price" style="font-size:15px;">${money(p.compareAtPrice)}</span> ` : ""}${money(effectivePrice)}</div>
            <p class="pd-desc">${safeText(p.description)}</p>
            ${specsHtml}
            ${colorHtml}
            ${variantHtml}
            <p class="pd-stock ${effectiveStock <= 0 ? "low" : ""}" id="pdStock">${effectiveStock > 0 ? `${effectiveStock} en stock` : "Rupture de stock"}</p>
            <button class="btn-primary" type="button" id="pdAddToCart" style="width:100%;" ${effectiveStock <= 0 ? "disabled" : ""}>${icon('shopping-cart')} Ajouter au panier</button>
          </div>
        </div>

        <div class="pd-section-divider">
          <div class="pd-section-title">Avis clients ${ratingInfo.count ? `(${ratingInfo.count})` : ""}</div>
          ${reviews.length ? reviews.map((r) => `
            <div class="review-card">
              <div class="review-card-head">
                <span class="review-author">${safeText(maskCustomerName(r.customerName))}</span>
                <span class="review-date">${new Date(r.createdAt).toLocaleDateString("fr-FR")}</span>
              </div>
              <div class="review-stars">${starsHtml(r.rating)}</div>
              ${r.comment ? `<p class="review-comment">${safeText(r.comment)}</p>` : ""}
            </div>
          `).join("") : `<p class="muted" style="margin-bottom:14px;">Soyez le premier à donner votre avis sur ce produit.</p>`}

          ${customer ? `
            <form id="reviewForm" style="margin-top:12px;">
              <label style="font-size:13px;font-weight:800;color:var(--ink);display:block;margin-bottom:8px;">Laisser un avis</label>
              <div class="review-form-stars" id="reviewFormStars">
                ${[1,2,3,4,5].map((n) => `<button type="button" class="review-form-star ${n <= state.productDetail.reviewRating ? "active" : ""}" data-review-star="${n}">${icon('star')}</button>`).join("")}
              </div>
              <textarea id="reviewComment" placeholder="Votre commentaire (facultatif)" style="width:100%;border:1.5px solid var(--border);border-radius:10px;padding:10px;min-height:64px;margin-bottom:10px;"></textarea>
              <button class="btn-soft" type="submit">Publier mon avis</button>
              <p id="reviewError" class="error-text"></p>
            </form>
          ` : `<p class="muted">Connectez-vous à votre compte pour laisser un avis.</p>`}
        </div>

        ${similar.length ? `
          <div class="pd-section-divider">
            <div class="pd-section-title">Produits similaires</div>
            <div class="similar-strip">
              ${similar.map((sp) => `
                <div class="similar-card" data-open-product="${sp.id}" role="button" tabindex="0">
                  <div class="simg">${sp.imageUrl ? `<img src="${safeText(sp.imageUrl)}" alt="${safeText(sp.name)}">` : `<div class="image-fallback">${icon('image')}</div>`}</div>
                  <div class="sinfo">
                    <div class="sname">${safeText(sp.name)}</div>
                    <div class="sprice">${money(sp.price)}</div>
                  </div>
                </div>
              `).join("")}
            </div>
          </div>
        ` : ""}
      `;

      setTimeout(() => {
        $$("[data-select-image]").forEach((btn) => btn.addEventListener("click", () => {
          state.productDetail.activeImage = btn.dataset.selectImage;
          renderProductDetailModal(productId);
        }));
        $$("[data-select-ml]").forEach((btn) => btn.addEventListener("click", () => {
          state.productDetail.selectedMl = btn.dataset.selectMl;
          renderProductDetailModal(productId);
        }));
        $$("[data-select-color]").forEach((btn) => btn.addEventListener("click", () => {
          state.productDetail.selectedColor = btn.dataset.selectColor;
          renderProductDetailModal(productId);
        }));
        $("#pdAddToCart")?.addEventListener("click", () => addToCartWithVariant(productId));

        $("#pdShareBtn")?.addEventListener("click", () => {
          const shareUrl = `${window.location.origin}${window.location.pathname}?produit=${productId}`;
          if (navigator.share) {
            navigator.share({ title: p.name, text: `Découvrez "${p.name}" sur ${state.settings.storeName || "MarketHaiti"} !`, url: shareUrl }).catch(() => {});
          } else {
            $("#pdShareMenu").hidden = !$("#pdShareMenu").hidden;
          }
        });
        $$("[data-share-channel]").forEach((btn) => btn.addEventListener("click", () => {
          const shareUrl = `${window.location.origin}${window.location.pathname}?produit=${productId}`;
          const text = `Découvrez "${p.name}" sur ${state.settings.storeName || "MarketHaiti"} !`;
          const channel = btn.dataset.shareChannel;
          const links = {
            whatsapp: `https://wa.me/?text=${encodeURIComponent(text + " " + shareUrl)}`,
            facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(shareUrl)}`,
            messenger: `https://www.facebook.com/dialog/send?link=${encodeURIComponent(shareUrl)}&app_id=&redirect_uri=${encodeURIComponent(shareUrl)}`,
            twitter: `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(shareUrl)}`,
            telegram: `https://t.me/share/url?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(text)}`
          };
          if (channel === "copy") {
            navigator.clipboard?.writeText(shareUrl).then(() => {
              btn.innerHTML = `${icon('check')} Lien copié !`;
              setTimeout(() => { btn.innerHTML = `${icon('copy')} Copier le lien`; }, 1800);
            });
          } else if (links[channel]) {
            window.open(links[channel], "_blank", "noopener,noreferrer");
          }
          $("#pdShareMenu").hidden = true;
        }));

        $$("[data-review-star]").forEach((btn) => btn.addEventListener("click", () => {
          state.productDetail.reviewRating = Number(btn.dataset.reviewStar);
          renderProductDetailModal(productId);
        }));
        $("#reviewForm")?.addEventListener("submit", async (e) => {
          e.preventDefault();
          const cust = currentCustomer();
          if (!cust) return;
          if (!state.productDetail.reviewRating) {
            $("#reviewError").textContent = "Choisissez une note avant de publier.";
            return;
          }
          const review = {
            id: uid("review"),
            productId,
            customerName: cust.name,
            rating: state.productDetail.reviewRating,
            comment: $("#reviewComment").value.trim(),
            createdAt: new Date().toISOString()
          };
          const ok = await writeRow("reviews", review);
          if (!ok) {
            $("#reviewError").textContent = "Impossible d'enregistrer votre avis pour le moment. Réessayez plus tard.";
            return;
          }
          state.reviews.push(review);
          state.productDetail.reviewRating = 0;
          renderProductDetailModal(productId);
          renderProductsGrid();
        });
      }, 0);
    }

    function addToCartWithVariant(productId) {
      const p = state.products.find((pp) => pp.id === productId);
      if (!p) return;
      const volumes = Array.isArray(p.priceByVolume) ? p.priceByVolume : [];
      const colors = Array.isArray(p.colorOptions) ? p.colorOptions.filter(Boolean) : [];
      const selectedVolume = volumes.find((v) => v.ml === state.productDetail.selectedMl) || null;
      const selectedColor = state.productDetail.selectedColor || "";

      if (volumes.length && !selectedVolume) {
        alert("Veuillez choisir une contenance avant d'ajouter au panier.");
        return;
      }
      if (colors.length && !selectedColor) {
        alert("Veuillez choisir une couleur avant d'ajouter au panier.");
        return;
      }

      const effectivePrice = selectedVolume && selectedVolume.price != null ? selectedVolume.price : p.price;
      const effectiveStock = Number(p.stock);
      // Identifiant de ligne de panier unique par produit + couleur + contenance choisies
      const cartLineId = [p.id, selectedColor, selectedVolume?.ml].filter(Boolean).join("::");
      const variantLabel = [selectedColor, selectedVolume?.ml].filter(Boolean).join(" · ");

      const existing = state.cart.find((item) => item.cartLineId === cartLineId);
      if (existing) {
        if (existing.quantity < effectiveStock) {
          existing.quantity++;
        } else {
          alert(`Stock limité à ${effectiveStock} article(s)`);
          return;
        }
      } else {
        state.cart.push({
          ...p,
          id: p.id,
          cartLineId,
          price: effectivePrice,
          stock: effectiveStock,
          variantId: "",
          variantLabel,
          quantity: 1
        });
      }
      writeLocalCart(state.cart);
      renderCartPanel();
      closeModal();
    }

    function renderFilters() {
      const activeProducts = state.products.filter((p) => p.isActive !== false);
      const categories = [...new Set(activeProducts.map((p) => p.category))];
      const vendors = [...new Set(activeProducts.map((p) => p.vendorName))];

      $("#categoryFilters").innerHTML = categories.map((cat) => `
        <button class="filter-btn ${state.filters.category === cat ? "active" : ""}" type="button" data-filter-category="${cat}">${safeText(cat)}</button>
      `).join("");

      $("#vendorFilters").innerHTML = vendors.map((vendor) => `
        <button class="filter-btn ${state.filters.vendor === vendor ? "active" : ""}" type="button" data-filter-vendor="${vendor}">
          ${activeProducts.find((p) => p.vendorName === vendor)?.vendorLogo ? `<img src="${activeProducts.find((p) => p.vendorName === vendor).vendorLogo}" style="width:16px;height:16px;border-radius:50%;margin-right:4px;">` : ""}
          ${safeText(vendor)}
        </button>
      `).join("");

      // Vitrine "catégories populaires" sur la page d'accueil (mêmes catégories,
      // simple raccourci visuel qui applique le même filtre que la sidebar).
      const showcase = $("#categoryShowcase");
      if (showcase) {
        showcase.innerHTML = categories.slice(0, 8).map((cat) => `
          <button class="category-chip-card ${state.filters.category === cat ? "active" : ""}" type="button" data-filter-category="${cat}">
            ${icon(categoryIcon(cat))}
            <span>${safeText(cat)}</span>
          </button>
        `).join("") || `<p class="muted">Aucune catégorie pour le moment.</p>`;
      }

      // Filtre "avis clients" (façon Amazon : note minimum). Reste discret si
      // aucun avis n'a encore été laissé — les boutons restent utilisables,
      // simplement aucun produit n'aura de note tant que reviews est vide.
      const ratingBox = $("#ratingFilters");
      if (ratingBox) {
        ratingBox.innerHTML = [4, 3, 2, 1].map((min) => `
          <button class="rating-filter-btn ${state.filters.minRating === min ? "active" : ""}" type="button" data-filter-rating="${min}">
            ${starsHtml(min)} <span>&amp; plus</span>
          </button>
        `).join("") + `
          <button class="rating-filter-btn ${state.filters.minRating === 0 ? "active" : ""}" type="button" data-filter-rating="0">Toutes les notes</button>
        `;
      }
    }

    // EVENT LISTENERS
    document.addEventListener("click", async (event) => {
      if (event.target.id === "filterOverlay") {
        $("#filtersSidebar").classList.remove("open");
        $("#filterOverlay").classList.remove("open");
        $("#supportBubble").style.display = "block";
      }
      const openTarget = event.target.closest("[data-open-product]");
      if (openTarget) {
        renderProductDetailModal(openTarget.dataset.openProduct);
        openModal("#productDetailModal");
      }

      const shareMenu = $("#pdShareMenu");
      if (shareMenu && !shareMenu.hidden && !shareMenu.contains(event.target) && !event.target.closest("#pdShareBtn")) {
        shareMenu.hidden = true;
      }

      const target = event.target.closest("button");
      if (!target) return;

      if (target.matches("[data-add-to-cart]")) {
        const product = state.products.find((p) => p.id === target.dataset.addToCart);
        if (!product) return;
        const cartLineId = product.id;
        const existing = state.cart.find((item) => item.cartLineId === cartLineId);
        if (existing) {
          if (existing.quantity < Number(product.stock)) {
            existing.quantity++;
          } else {
            alert(`Stock limité à ${product.stock} article(s)`);
          }
        } else {
          state.cart.push({ ...product, cartLineId, variantId: "", variantLabel: "", quantity: 1 });
        }
        writeLocalCart(state.cart);
        renderCartPanel();
      }

      if (target.matches("[data-qty-plus]")) {
        const item = state.cart.find((i) => i.cartLineId === target.dataset.qtyPlus);
        const product = state.products.find((p) => p.id === item?.id);
        const cap = item ? Number(item.stock ?? product?.stock ?? 0) : 0;
        if (item && item.quantity < cap) {
          item.quantity++;
        } else if (item) {
          alert(`Stock limité à ${cap} article(s)`);
        }
        writeLocalCart(state.cart);
        renderCartPanel();
      }

      if (target.matches("[data-qty-minus]")) {
        const item = state.cart.find((i) => i.cartLineId === target.dataset.qtyMinus);
        if (item && item.quantity > 1) item.quantity--;
        writeLocalCart(state.cart);
        renderCartPanel();
      }

      if (target.matches("[data-remove-item]")) {
        state.cart = state.cart.filter((i) => i.cartLineId !== target.dataset.removeItem);
        writeLocalCart(state.cart);
        renderCartPanel();
      }

      if (target.matches("[data-copy-pay-number]")) {
        const value = target.dataset.copyPayNumber;
        if (value) copyToClipboard(value);
      }

      // Vérification en direct d'un paiement MonCash (Bazik) depuis le compte
      if (target.matches("[data-verify-payment]")) {
        const orderId = target.dataset.verifyPayment;
        target.disabled = true;
        target.innerHTML = `${icon('loader-circle','spin')} Vérification...`;
        try {
          const res = await fetch(PAYMENT_VERIFY_URL, {
            method: "POST",
            headers: { "Content-Type": "application/json", "Authorization": `Bearer ${SUPABASE_ANON_KEY}`, "apikey": SUPABASE_ANON_KEY },
            body: JSON.stringify({ orderId })
          });
          const data = await res.json();
          const order = state.orders.find((o) => o.id === orderId);
          if (order && data.paymentStatus) order.paymentStatus = data.paymentStatus;
          if (data.paymentStatus === "succeeded") {
            alert(`Paiement confirmé — commande ${orderId} validée.`);
          } else if (data.paymentStatus === "failed") {
            alert(`Le paiement de la commande ${orderId} a échoué.`);
          } else {
            alert(`Le paiement de la commande ${orderId} n'est pas encore confirmé. Réessayez dans un instant.`);
          }
          renderAccountModal();
        } catch {
          target.disabled = false;
          target.innerHTML = `${icon('refresh-cw')} Vérifier le paiement`;
          alert("Impossible de vérifier le paiement pour le moment. Réessayez.");
        }
      }

      if (target.matches("[data-filter-category]")) {
        state.filters.category = target.dataset.filterCategory;
        renderFilters();
        renderProductsGrid();
      }

      if (target.matches("[data-filter-vendor]")) {
        state.filters.vendor = target.dataset.filterVendor;
        renderFilters();
        renderProductsGrid();
      }

      if (target.matches("[data-filter-rating]")) {
        state.filters.minRating = Number(target.dataset.filterRating);
        renderFilters();
        renderProductsGrid();
      }

      if (target.matches("#resetFilters")) {
        state.filters = { category: "", vendor: "", search: "", sort: "featured", priceMin: null, priceMax: null, minRating: 0 };
        renderFilters();
        renderProductsGrid();
        $("#searchInput").value = "";
        $("#sortSelect").value = "featured";
        if ($("#priceMinInput")) $("#priceMinInput").value = "";
        if ($("#priceMaxInput")) $("#priceMaxInput").value = "";
      }

      if (target.matches("#mobileFilterToggle")) {
        $("#filtersSidebar").classList.add("open");
        $("#filterOverlay").classList.add("open");
        $("#supportBubble").style.display = "none";
      }

      if (target.matches("#closeFilterDrawer") || target.matches("#applyFilterDrawer")) {
        $("#filtersSidebar").classList.remove("open");
        $("#filterOverlay").classList.remove("open");
        $("#supportBubble").style.display = "block";
      }

      if (target.matches("#cartBtn")) {
        $("#cartOverlay").classList.add("open");
        $("#cartPanel").classList.add("open");
        $("#supportBubble").style.display = "none";
      }

      if (target.matches("#closeCart")) {
        $("#cartOverlay").classList.remove("open");
        $("#cartPanel").classList.remove("open");
        $("#supportBubble").style.display = "block";
      }

      if (target.matches("#accountBtn") || target.matches("[data-open-account]")) {
        renderAccountModal();
        openModal("#accountModal");
      }

      if (target.matches("#checkoutBtn")) {
        const customer = currentCustomer();
        if (!customer) {
          renderAccountModal();
          openModal("#accountModal");
          return;
        }
        const total = state.cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
        $("#checkoutTotal").textContent = money(total);
        $("#deliveryPhone").value = customer.phone;
        // Méthodes de paiement proposées = celles activées dans l'admin
        const methods = enabledPaymentMethods();
        $("#paymentMethod").innerHTML = methods.map((m) => `<option value="${safeText(m.value)}">${safeText(m.label)}</option>`).join("") || `<option value="">Aucune méthode configurée</option>`;
        updatePaymentDetailsUI();
        openModal("#checkoutModal");
      }

      if (target.matches("[data-close-modal]")) closeModal();
      if (target.matches("[data-scroll-products]")) {
        document.getElementById("productsSection").scrollIntoView({ behavior: "smooth" });
      }
    });

    const copyToClipboard = async (text) => {
      try {
        await navigator.clipboard.writeText(text);
        alert("Copié dans le presse-papiers !");
      } catch (err) {
        prompt("Copier manuellement ce texte :", text);
      }
    };

    // Affiche les détails de paiement (numéros MonCash/NatCash ou compte
    // bancaire) pour la méthode actuellement sélectionnée. Fonction nommée
    // pour pouvoir être appelée à la fois au changement de sélection ET à
    // l'ouverture du checkout (la méthode par défaut nécessite déjà une
    // preuve de paiement depuis le retrait du paiement à la livraison).
    function updatePaymentDetailsUI() {
      const method = $("#paymentMethod").value;
      const detailsBox = $("#paymentDetailsBox");
      const proofBox = $("#proofUploadBox");
      const proofInput = $("#paymentProof");
      const cfg = findPaymentConfig(method) || {};
      const logoImg = cfg.logoUrl ? `<img src="${safeText(cfg.logoUrl)}" alt="${safeText(method)}" class="pay-method-logo">` : "";
      const instructions = cfg.instructions ? `<div class="muted" style="margin-top:8px;">${safeText(cfg.instructions)}</div>` : "";

      if (!method) { detailsBox.hidden = true; proofBox.hidden = true; return; }

      if (method === "MonCash") {
        // Paiement automatique via Bazik : pas de numéro manuel ni de preuve,
        // le client est redirigé vers la page de paiement MonCash sécurisée.
        $("#paymentDetails").innerHTML = `<div class="payment-detail-item pay-method-head">${logoImg}<strong>MonCash</strong></div><div class="payment-detail-item">${icon('lock')} Paiement sécurisé en direct — vous serez redirigé vers MonCash pour confirmer, puis la commande sera validée automatiquement.</div>${instructions}`;
        detailsBox.hidden = false;
        proofBox.hidden = true;
        if (proofInput) { proofInput.required = false; proofInput.value = ""; }
      } else if (method === "NatCash") {
        // Mode manuel (NatCash) : le client envoie sur un numéro et uploade
        // une preuve que l'admin valide ensuite.
        const data = state.payments[method.toLowerCase()] || {};
        let html = "";
        if (data.numbers && data.numbers.length > 0) {
          const lines = data.numbers.map(n => {
            const value = typeof n === 'string' ? n : n.number;
            const label = typeof n === 'string' ? value : `${n.name ? `<strong>${n.name}</strong> - ` : ''}${n.number}`;
            return `<div class="payment-detail-row"><span>${label}</span><button type="button" data-copy-pay-number="${safeText(value)}" class="btn-soft" title="Copier le numéro">${icon('copy')}</button></div>`;
          });
          html = `<div class="payment-detail-item pay-method-head">${logoImg}<strong>${method}</strong></div>${lines.join('')}<div style="margin-top:10px;">Compte: ${safeText(data.account)}</div>${instructions}`;
        } else {
          html = `<div class="payment-detail-item pay-method-head">${logoImg}<strong>${method}</strong></div><div class="payment-detail-item">Aucun numéro ${method} configuré.</div>${instructions}`;
        }
        $("#paymentDetails").innerHTML = html;
        detailsBox.hidden = false;
        proofBox.hidden = false;
        if (proofInput) proofInput.required = true;
      } else if (method === "Compte bancaire") {
        const bank = state.payments.bank;
        const html = `<div class="payment-detail-item pay-method-head">${logoImg}<strong>${safeText(bank.bankName || "Compte bancaire")}</strong></div><div class="payment-detail-item">Titulaire: ${bank.accountHolder}<br>Compte: ${bank.accountNumber}</div>${instructions}`;
        $("#paymentDetails").innerHTML = html;
        if (proofInput) proofInput.required = true;
        detailsBox.hidden = false;
        proofBox.hidden = false;
      } else {
        // Méthode personnalisée (ajoutée dans l'admin) : paiement manuel,
        // affiche logo + instructions + preuve obligatoire.
        const html = `<div class="payment-detail-item pay-method-head">${logoImg}<strong>${safeText(method)}</strong></div>${instructions || `<div class="payment-detail-item muted">Suivez les instructions du marchand pour cette méthode.</div>`}`;
        $("#paymentDetails").innerHTML = html;
        if (proofInput) proofInput.required = true;
        detailsBox.hidden = false;
        proofBox.hidden = false;
      }
    }
    $("#paymentMethod").addEventListener("change", updatePaymentDetailsUI);

    // HANDLE CHECKOUT SUBMIT
    $("#checkoutForm").addEventListener("submit", async (e) => {
      e.preventDefault();
      const customer = currentCustomer();
      if (!customer) return;

      const submitBtn = $("#checkoutForm button[type='submit']");
      const deliveryAddress = $("#deliveryAddress").value.trim();
      const deliveryPhone = $("#deliveryPhone").value.trim();
      const notes = $("#orderNotes").value.trim();
      const paymentMethod = $("#paymentMethod").value;
      let proofUrl = "";

      // Validate stock before creating order (le stock est au niveau du produit ;
      // on additionne les quantités si plusieurs lignes du panier concernent le
      // même produit avec des contenances différentes).
      const qtyByProduct = {};
      state.cart.forEach((item) => { qtyByProduct[item.id] = (qtyByProduct[item.id] || 0) + Number(item.quantity); });
      const overProductId = Object.keys(qtyByProduct).find((pid) => {
        const p = state.products.find((pp) => pp.id === pid);
        return !p || qtyByProduct[pid] > Number(p.stock);
      });
      if (overProductId) {
        const overProduct = state.products.find((pp) => pp.id === overProductId);
        alert(`Quantité demandée pour "${overProduct?.name || 'ce produit'}" dépasse le stock disponible (${overProduct?.stock || 0}). La commande ne peut pas être passée.`);
        return;
      }

      // Upload de la preuve de paiement vers le bucket Supabase Storage "payment-proofs"
      const proofInput = document.getElementById("paymentProof");
      if (proofInput.files.length > 0) {
        if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Envoi de la preuve..."; }
        proofUrl = await uploadFileToBucket("payment-proofs", proofInput.files[0]);
        if (!proofUrl) {
          if (submitBtn) { submitBtn.disabled = false; submitBtn.innerHTML = `${icon('check')} Valider la commande`; }
          $("#checkoutError").textContent = "Échec de l'envoi de la preuve de paiement. Veuillez réessayer.";
          return;
        }
      }

      const order = {
        id: uid("order"),
        customerId: customer.id,
        customerName: customer.name,
        customerUsername: customer.username || "",
        customerPhone: customer.phone,
        address: deliveryAddress,
        receptionPhone: deliveryPhone,
        notes,
        paymentMethod,
        proofUrl,
        items: state.cart.map((item) => ({ id: item.id, vendorId: item.vendorId || "", name: item.name, vendorName: item.vendorName, quantity: item.quantity, price: item.price, variantLabel: item.variantLabel || "" })),
        vendorId: state.cart[0]?.vendorId || "",
        vendorName: state.cart[0]?.vendorName || "",
        total: state.cart.reduce((sum, item) => sum + item.price * item.quantity, 0),
        status: "En attente",
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      const updatedProducts = [];
      Object.keys(qtyByProduct).forEach((pid) => {
        const product = state.products.find((p) => p.id === pid);
        if (product) {
          product.stock = Math.max(0, Number(product.stock) - qtyByProduct[pid]);
          updatedProducts.push(product);
        }
      });
      for (const product of updatedProducts) {
        await writeRow("products", product);
      }

      state.orders.push(order);
      await writeRow("orders", order);

      // MONCASH via BAZIK : redirection immédiate vers la page de paiement
      // hébergée — pas de preuve manuelle. Au retour, bazik-verify-payment
      // interroge l'API Bazik en direct et valide la commande.
      if (paymentMethod === "MonCash") {
        if (submitBtn) { submitBtn.disabled = true; submitBtn.innerHTML = `${icon('loader-circle','spin')} Redirection vers MonCash...`; }
        state.cart = [];
        writeLocalCart(state.cart);
        try {
          const res = await fetch(PAYMENT_CREATE_URL, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${SUPABASE_ANON_KEY}`,
              "apikey": SUPABASE_ANON_KEY,
            },
            body: JSON.stringify({ orderId: order.id }),
          });
          const data = await res.json();
          if (!res.ok || !data.payment_url) {
            throw new Error(data?.error || "Réponse invalide du serveur de paiement");
          }
          // Redirection immédiate — le lien MonCash est à usage unique et ne
          // doit pas rester cliquable (précharge = jeton consommé).
          window.location.href = data.payment_url;
          return;
        } catch (err) {
          if (submitBtn) { submitBtn.disabled = false; submitBtn.innerHTML = `${icon('check')} Valider la commande`; }
          $("#checkoutError").textContent = `Votre commande ${order.id} est enregistrée, mais la redirection vers MonCash a échoué. Contactez-nous ou réessayez.`;
          return;
        }
      }

      state.cart = [];
      writeLocalCart(state.cart);

      if (submitBtn) { submitBtn.disabled = false; submitBtn.innerHTML = `${icon('check')} Valider la commande`; }
      alert(`Commande ${order.id} enregistrée. Votre preuve de paiement a bien été reçue et la commande sera vérifiée.`);
      closeModal();
      renderCartPanel();
      renderProductsGrid();
      $("#checkoutForm").reset();
    });

    // RECOVERY FORM — définit le nouveau mot de passe (arrivée via le lien email)
    $("#recoveryForm").addEventListener("submit", async (e) => {
      e.preventDefault();
      const newPassword = $("#recoveryPassword").value;
      const submitBtn = $("#recoveryForm button[type='submit']");
      $("#recoveryError").textContent = "";
      if (submitBtn) submitBtn.disabled = true;
      try {
        const { data: userData, error: updateError } = await supabase.auth.updateUser({ password: newPassword });
        if (updateError) {
          $("#recoveryError").textContent = "Impossible de mettre à jour le mot de passe. Le lien a peut-être expiré.";
          return;
        }
        // Garde le mot de passe local (passwordHash) synchronisé pour que la
        // connexion habituelle (téléphone/username) continue de fonctionner.
        const email = (userData?.user?.email || "").toLowerCase();
        const match = state.customers.find((c) => c.email?.toLowerCase() === email);
        if (match) {
          match.passwordHash = await sha256(newPassword);
          await writeRow("customers", match);
          localStorage.setItem(STORAGE.session, match.id);
        }
        alert("Votre mot de passe a été mis à jour avec succès. Vous êtes connecté.");
        closeModal();
        state.authMode = "signin";
        renderAccountModal();
      } finally {
        if (submitBtn) submitBtn.disabled = false;
      }
    });

    // SEARCH INPUT
    $("#searchInput").addEventListener("input", (e) => {
      state.filters.search = e.target.value;
      renderProductsGrid();
    });

    // SORT SELECT
    $("#sortSelect").addEventListener("change", (e) => {
      state.filters.sort = e.target.value;
      renderProductsGrid();
    });

    // FILTRE PRIX (min / max)
    $("#priceMinInput")?.addEventListener("input", (e) => {
      state.filters.priceMin = e.target.value === "" ? null : Number(e.target.value);
      renderProductsGrid();
    });
    $("#priceMaxInput")?.addEventListener("input", (e) => {
      state.filters.priceMax = e.target.value === "" ? null : Number(e.target.value);
      renderProductsGrid();
    });

    function openModal(id) {
      $("#modalOverlay").classList.add("open");
      $(id).classList.add("open");
      $("#supportBubble").style.display = "none";
    }

    function closeModal() {
      $("#modalOverlay").classList.remove("open");
      $$(".modal").forEach((m) => m.classList.remove("open"));
      $("#supportBubble").style.display = "block";
    }

    window.addEventListener("storage", () => {
      // Reload data when localStorage changes (cart updates from other tabs)
      state.cart = readLocalCart();
      renderCartPanel();
    });

    // Wait for Supabase to be initialized before starting app
  